const usernames =
  ($json.usernames || [])
    .slice(0, 6);

const visual =
  $json.visualMutation || {};

const seo =
  $json.seo || {};

const keyword =
  $json.keyword || 'Gaming Usernames';

const title =
  seo.pinterestTitle || keyword;

// --- BANCO DE OPCIONES EXPANDIDO PARA MAXIMA ALEATORIEDAD ---

const compositions = [
  'dynamic diagonal split screen',
  'asymmetrical tech-magazine layout',
  'centered heroic movie poster composition',
  'rule-of-thirds cinematic gaming setup',
  'vertical grid alignment with strong depth of field',
  'overlapping futuristic polaroid panels',
  'geometric cyberpunk collage layout',
  'clean isometric corporate gaming interface',
  'minimalist multi-panel visual grid',
  'high-contrast split-tone hero focus'
];
const composition = visual.composition || compositions[Math.floor(Math.random() * compositions.length)];

const lightings = [
  'bioluminescent neon backlight with sharp rim light',
  'cinematic moody esports lighting with dramatic shadows',
  'high-contrast cyberpunk chaser lights and soft fog illumination',
  'futuristic synthwave glowing ambience with lens flares',
  'hyper-bright gaming arena strobe lights and intense glow',
  'dark moody low-key studio lighting with striking accent colors',
  'ray-traced volumetric light beams cutting through haze',
  'cybernetic pulse lighting with shifting color shadows',
  'dramatic under-lighting from a glowing tech console',
  'subtle pastel studio softbox setup with sharp metallic glare'
];
const lighting = visual.lighting || lightings[Math.floor(Math.random() * lightings.length)];

const colorPalettes = [
  'vibrant cyberpunk neon, electric violet, acid green, deep obsidian',
  'dark esports palette, hot crimson, electric blue, charcoal black',
  'monochromatic dark mode, stealth gray, toxic neon yellow highlights',
  'retro synthwave tones, pastel magenta, cyan, deep cosmic purple',
  'luxury premium gaming colors, matte black, metallic gold, royal sapphire',
  'glitch aesthetic multi-color mix, glitch pink, corrupted cyan, deep void navy',
  'mecha armor industrial colors, arctic white, carbon fiber black, orange alert',
  'deep phantom space violet, cosmic stardust white, nebula indigo',
  'toxic venom green, nuclear hazard yellow, dark graphite gray',
  'minimalist high-fashion gaming, pure alabaster, soft beige, stark matte black'
];
const colors = visual.colors || colorPalettes[Math.floor(Math.random() * colorPalettes.length)];

const typographies = [
  'sleek minimalist sci-fi typography, high-contrast crisp text',
  'bold aggressive esports typography, heavy block letters',
  'modern clean geometric sans-serif fonts, razor-sharp edges',
  'glowing electronic HUD digital typeface, high legibility',
  'futuristic stencil tech lettering, premium layout text',
  'brutalist ultra-bold typography with digital tech subtext',
  'cyberpunk liquid-neon lettering style with high contrast',
  'sharp metallic chiseled gaming font with outer outer glow',
  'clean pixelated arcade font modern adaptation, sharp tracking',
  'premium tech-magazine layout typography, ultra thin accents'
];
const typography = visual.typography || typographies[Math.floor(Math.random() * typographies.length)];

const cameras = [
  'dynamic low-angle heroic shot',
  'close-up intense portrait view',
  'three-quarter medium shot with dramatic perspective',
  'cinematic wide shot cropped for vertical framing',
  'extreme close-up on gaming equipment and character face',
  'dramatic dutch angle action shot with high perspective lines',
  'macro view focusing over the shoulder of the player',
  'symmetrical eye-level frontal power pose',
  'dynamic fisheye cybernetic interface perspective',
  'cinematic profile shot with sharp focus on cyber-implants'
];
const camera = visual.camera || cameras[Math.floor(Math.random() * cameras.length)];

const renderStyles = [
  'next-gen cinematic 3D render, flawless octane shading',
  'ultra detailed digital art, crisp vector accents',
  'photorealistic gaming CGI, Unreal Engine 5 aesthetic',
  'stylized premium illustration, high-end comic shading',
  'polished esports concept art, macro-level digital textures',
  'gritty hyper-detailed cyber-noir graphical novel artwork',
  'smooth digital airbrushing with highly polished vector overlays',
  'futuristic tech-concept schematics art overlayed on 3D model',
  'high-contrast stylized vaporwave graphic design rendering',
  'matte painting masterpiece with incredible cinematic realism'
];
const renderStyle = visual.renderStyle || renderStyles[Math.floor(Math.random() * renderStyles.length)];

const moods = [
  'hypnotic futuristic hype, high-energy arcade tech',
  'competitive gaming energy, intense focus, pro-player vibe',
  'mysterious dark web hacker atmosphere, high tech tension',
  'epic virtual reality adventure, legendary championship mood',
  'cyberpunk underworld adrenaline, chaotic fast-paced streaming',
  'zen hyper-focused flow state, professional streaming focus',
  'triumphant tournament victory celebration, pure esports ecstasy',
  'rebellious underground neon skater crew vibe',
  'high-tech tactical espionage, precise military stealth gaming',
  'limitless virtual simulation power, transcendent gaming aura'
];
const mood = visual.mood || moods[Math.floor(Math.random() * moods.length)];

// --- CATEGORIAS COMPLEMENTARIAS ---

const usernameText =
  usernames.join(', ');

const characterPrompts = [
  'anonymous esports gamer character',
  'futuristic gaming character',
  'competitive tactical gamer',
  'stylized streamer character',
  'cyberpunk esports player',
  'dark gaming avatar',
  'cyber-enhanced elite pro-gamer',
  'futuristic android streamer with glowing hair',
  'neon-masked synthwave hacker character',
  'holographic neon esports avatar',
  'mecha-armor pilot wearing an advanced gaming visor',
  'female tech-wear streamer with custom glowing headphones',
  'phantom esports rogue assassin avatar with glowing eyes',
  'cyber-samurai pro gamer with a katana neon controller',
  'streetwear-styled virtual reality influencer avatar',
  'tactical specs operative monitoring dual tech screens'
];
const character = characterPrompts[Math.floor(Math.random() * characterPrompts.length)];

const layouts = [
  'usernames displayed in glowing UI panels',
  'gaming names shown in futuristic interface',
  'stacked usernames with esports HUD design',
  'neon gamer tags floating beside character',
  'competitive username layout for pinterest',
  'usernames embedded in clean floating holographic glass widgets',
  'gamer tags integrated into a sleek vertical cyberpunk timeline',
  'names arranged in sharp, minimalist laser-etched data boxes',
  'clean geometric scoreboard layout inside a streamer overlay',
  'usernames beautifully integrated into neon street signs',
  'asymmetric layout with a massive glowing text block on the left',
  'curved tactical HUD circles surrounding the username lists'
];
const usernameLayout = layouts[Math.floor(Math.random() * layouts.length)];

// --- GENERACION DEL PROMPT ---

const prompt = `
Create a highly viral, high-conversion Pinterest gaming poster.

Main topic:
${keyword}

Visual style:
${renderStyle}

Mood:
${mood}

Lighting:
${lighting}

Color palette:
${colors}

Composition:
${composition}

Typography:
${typography}

Camera angle:
${camera}

Main character:
${character}

Layout:
${usernameLayout}

Featured usernames:
${usernameText}

The image should look like:
- high CTR Pinterest content
- viral gaming thumbnail
- premium esports branding
- modern gaming identity design
- highly polished social media creative

Requirements:
- vertical 2:3 pinterest aspect ratio
- extremely readable text
- clean visual hierarchy
- strong focal point
- cinematic depth
- modern esports aesthetic
- ultra high detail
- no blurry text
- no watermark
- no extra random words
- polished professional composition

Branding:
Include subtle TryhardNames branding at the bottom.

Style inspiration:
Pinterest viral gaming posters, esports thumbnails, gaming identity branding, modern streamer graphics.
`.trim();

return [
  {
    json: {
      ...$json,

      dalle: {
        prompt,
        size: '1024x1536',
        quality: 'high',
        style: 'vivid'
      }
    }
  }
];

function shuffle(arr) {
  return [...arr]
    .sort(() => Math.random() - 0.5);
}

const usernames =
  ($json.usernames || [])
    .slice(0, 5);

const hashtags =
  shuffle($json.hashtags || [])
    .slice(0, 6);

const keyword =
  $json.keyword || 'Gaming Usernames';

const title =
  $json.title ||
  `${keyword} | TryhardNames`;

const usernamePreview =
  usernames.join(', ');

const ctaPool = [
  'Find more usernames on TryhardNames.',
  'Discover more gaming names instantly.',
  'Get more tryhard usernames now.',
  'Explore more gamer tags on TryhardNames.',
  'Find your next gaming identity.'
];

const cta =
  ctaPool[
    Math.floor(Math.random() * ctaPool.length)
  ];

const descriptionTemplates = [

  `Discover ${keyword.toLowerCase()} for competitive players and gamers. Examples include ${usernamePreview}. ${cta}`,

  `Looking for ${keyword.toLowerCase()}? Try usernames like ${usernamePreview}. ${cta}`,

  `${keyword} perfect for competitive gaming, ranked matches, and online identity inspiration. Featured names: ${usernamePreview}. ${cta}`,

  `Unique ${keyword.toLowerCase()} curated for gamers, streamers, and esports players. Ideas: ${usernamePreview}. ${cta}`
];

const description =
  descriptionTemplates[
    Math.floor(Math.random() * descriptionTemplates.length)
  ];

const seo = {
  pinterestTitle:
    title.slice(0, 100),

  pinterestDescription:
    `${description}\n\n${hashtags.join(' ')}`.slice(0, 800),

  hashtags,

  keywordDensity: {
    primary: keyword,
    category: $json.category || null
  },

  engagementSignals: {
    usernamesUsed: usernames.length,
    hashtagsUsed: hashtags.length,
    ctaIncluded: true
  }
};

return [
  {
    json: {
      ...$json,
      seo
    }
  }
];

const workflowData = $getWorkflowStaticData('global');

const topics = [
  {
    topic: 'gamer-names',
    category: 'topic-hub',
    stylePreset: 'competitive_identity',
    weight: 10,
    boardId: '<PINTEREST_BOARD_ID_GAMER_NAMES>'
  },

  {
    topic: 'valorant-sweaty',
    category: 'valorant',
    stylePreset: 'dark_red_neon',
    weight: 10,
    boardId: '<PINTEREST_BOARD_ID_VALORANT_SWEATY>'
  },

  {
    topic: 'valorant-usernames',
    category: 'valorant',
    stylePreset: 'cinematic_esports',
    weight: 9,
    boardId: '<PINTEREST_BOARD_ID_VALORANT_USERNAMES>'
  },

  {
    topic: 'roblox-names',
    category: 'roblox',
    stylePreset: 'pastel_gaming',
    weight: 8,
    boardId: '<PINTEREST_BOARD_ID_ROBLOX_NAMES>'
  },

  {
    topic: 'roblox-tryhard',
    category: 'roblox',
    stylePreset: 'pink_neon_competitive',
    weight: 8,
    boardId: '<PINTEREST_BOARD_ID_ROBLOX_TRYHARD>'
  },

  {
    topic: 'fortnite-sweaty',
    category: 'fortnite',
    stylePreset: 'purple_gaming',
    weight: 9,
    boardId: '<PINTEREST_BOARD_ID_FORTNITE_SWEATY>'
  },

  {
    topic: 'league-of-legends',
    category: 'lol',
    stylePreset: 'emerald_fantasy',
    weight: 7,
    boardId: '<PINTEREST_BOARD_ID_LEAGUE_OF_LEGENDS>'
  },

  {
    topic: 'discord-usernames',
    category: 'social',
    stylePreset: 'modern_clean',
    weight: 6,
    boardId: '<PINTEREST_BOARD_ID_DISCORD_USERNAMES>'
  }
];

const avoidRepeatWindow = 4;

if (!workflowData.previousTopics) {
  workflowData.previousTopics = [];
}

const recentTopics =
  workflowData.previousTopics.slice(-avoidRepeatWindow);

const weightedPool = [];

for (const item of topics) {

  const recentlyUsed =
    recentTopics.includes(item.topic);

  let effectiveWeight =
    item.weight;

  if (recentlyUsed) {
    effectiveWeight =
      Math.max(1, Math.floor(item.weight * 0.25));
  }

  for (let i = 0; i < effectiveWeight; i++) {
    weightedPool.push(item);
  }
}

const selected =
  weightedPool[
    Math.floor(Math.random() * weightedPool.length)
  ];

workflowData.previousTopics.push(selected.topic);

if (workflowData.previousTopics.length > 20) {
  workflowData.previousTopics =
    workflowData.previousTopics.slice(-20);
}

const seasonalKey =
  new Date().toISOString().slice(0, 7);

return [
  {
    json: {
      topic: selected.topic,
      category: selected.category,
      stylePreset: selected.stylePreset,
      boardId: selected.boardId,

      rotationMeta: {
        antiRepetition: true,
        avoidRepeatWindow,
        seasonalKey,
        deterministicReady: true
      },

      generatedAt:
        new Date().toISOString()
    }
  }
];

const styleMap = {

  dark_red_neon: {
    lighting: [
      'dark red neon cinematic lighting',
      'aggressive tactical shadows',
      'high contrast red esports glow'
    ],

    colors: [
      'red and black',
      'dark crimson neon',
      'black tactical red'
    ]
  },

  cinematic_esports: {
    lighting: [
      'cinematic esports lighting',
      'blue rim lighting',
      'high contrast competitive glow'
    ],

    colors: [
      'blue esports neon',
      'dark navy gaming',
      'electric blue glow'
    ]
  },

  pastel_gaming: {
    lighting: [
      'soft pastel gaming glow',
      'pink ambient lighting',
      'cute aesthetic neon'
    ],

    colors: [
      'pink and blue',
      'pastel cyber aesthetic',
      'soft neon gradient'
    ]
  },

  pink_neon_competitive: {
    lighting: [
      'pink competitive neon',
      'purple gaming glow',
      'vibrant streamer lighting'
    ],

    colors: [
      'pink and purple',
      'neon magenta',
      'streamer aesthetic'
    ]
  },

  emerald_fantasy: {
    lighting: [
      'emerald fantasy glow',
      'mystical cinematic lighting',
      'dark fantasy atmosphere'
    ],

    colors: [
      'emerald green',
      'dark fantasy teal',
      'mystic green and black'
    ]
  },

  modern_clean: {
    lighting: [
      'minimal modern lighting',
      'clean soft shadows',
      'bright futuristic lighting'
    ],

    colors: [
      'white and blue',
      'minimal grayscale',
      'clean discord aesthetic'
    ]
  },

  purple_gaming: {
    lighting: [
      'purple gaming neon',
      'competitive streamer lighting',
      'dark violet glow'
    ],

    colors: [
      'purple and black',
      'dark violet cyberpunk',
      'streamer purple neon'
    ]
  }
};

const compositions = [
  'vertical pinterest poster composition',
  'gaming thumbnail layout',
  'large centered title with side character',
  'split layout with usernames on right side',
  'minimal clean centered layout',
  'cinematic esports poster composition',
  'dynamic diagonal action composition'
];

const typography = [
  'bold esports typography',
  'minimal futuristic typography',
  'glowing neon title text',
  'stacked gaming title',
  'competitive thumbnail typography'
];

const cameraAngles = [
  'close-up portrait',
  'dynamic action angle',
  'front-facing symmetrical portrait',
  'low-angle cinematic shot',
  'mid-shot gaming poster'
];

function randomItem(arr) {
  return arr[
    Math.floor(Math.random() * arr.length)
  ];
}

const preset =
  $json.stylePreset || 'cinematic_esports';

const selectedStyle =
  styleMap[preset] || styleMap.cinematic_esports;

const visualMutation = {

  lighting:
    randomItem(selectedStyle.lighting),

  colors:
    randomItem(selectedStyle.colors),

  composition:
    randomItem(compositions),

  typography:
    randomItem(typography),

  camera:
    randomItem(cameraAngles),

  renderStyle:
    Math.random() > 0.5
      ? 'ultra detailed digital art'
      : 'stylized esports illustration',

  mood:
    Math.random() > 0.5
      ? 'competitive gaming energy'
      : 'viral pinterest gaming design'
};

return [
  {
    json: {
      ...$json,
      visualMutation
    }
  }
];
